{
  "name": "MQTT 客户端",
  "name_en": "MQTT Client",
  "manufacturer": "",
  "description": "通用 MQTT 客户端组件，用于通过 MQTT 代理发布设备状态、订阅控制主题，并支持 Home Assistant 自动发现配置。它常用于将实验室设备、传感器或执行器接入消息总线，实现远程监控与集成。",
  "description_en": "A generic MQTT client component used to publish device states, subscribe to control topics, and support Home Assistant discovery configuration through an MQTT broker. It is commonly used to connect lab equipment, sensors, or actuators to a message bus for remote monitoring and integration.",
  "tag_hints": [
    "MQTT messaging",
    "Home Assistant discovery",
    "publish/subscribe",
    "device telemetry",
    "remote monitoring",
    "automation integration"
  ],
  "actions": [
    {
      "action_name": "auto-setupDevice",
      "description": "初始化用于通信的设备连接或接口。",
      "description_en": "Initialize the device connection or interface used for communication."
    },
    {
      "action_name": "auto-setupInitValues",
      "description": "设置初始主题值。",
      "description_en": "Set initial topic values."
    },
    {
      "action_name": "auto-setupClientTopics",
      "description": "配置客户端需要使用的 MQTT 主题。",
      "description_en": "Configure the MQTT topics required by the client."
    },
    {
      "action_name": "auto-setupHassDiscoveryConfigs",
      "description": "配置 Home Assistant 自动发现主题与参数。",
      "description_en": "Configure Home Assistant discovery topics and parameters."
    },
    {
      "action_name": "auto-setupSubscribeTopics",
      "description": "配置需要订阅的 MQTT 主题。",
      "description_en": "Configure the MQTT topics to subscribe to."
    },
    {
      "action_name": "auto-getRefreshRate",
      "description": "获取默认刷新轮询速率。",
      "description_en": "Get the default refresh polling rate."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询已连接设备的数据。",
      "description_en": "Poll data from the connected device."
    },
    {
      "action_name": "auto-daemon_kill",
      "description": "处理守护进程终止或中断请求。",
      "description_en": "Handle daemon termination or interrupt requests."
    },
    {
      "action_name": "auto-on_connect",
      "description": "处理与 MQTT 代理建立连接后的事件。",
      "description_en": "Handle the event after connecting to the MQTT broker."
    },
    {
      "action_name": "auto-subsribe_topics",
      "description": "订阅已配置的 MQTT 主题。",
      "description_en": "Subscribe to the configured MQTT topics."
    },
    {
      "action_name": "auto-publish_avail_topics",
      "description": "发布全部可用性主题状态。",
      "description_en": "Publish the status of all availability topics."
    },
    {
      "action_name": "auto-publish_state_topics",
      "description": "发布全部状态主题数据。",
      "description_en": "Publish data for all state topics."
    },
    {
      "action_name": "auto-on_message",
      "description": "处理从 MQTT 代理接收到的消息。",
      "description_en": "Handle messages received from the MQTT broker."
    },
    {
      "action_name": "auto-on_disconnect",
      "description": "处理与 MQTT 代理断开连接的事件。",
      "description_en": "Handle the event of disconnecting from the MQTT broker."
    },
    {
      "action_name": "auto-client_down",
      "description": "执行客户端关闭与清理。",
      "description_en": "Perform client shutdown and cleanup."
    },
    {
      "action_name": "auto-publish_avail",
      "description": "发布单个可用性主题状态。",
      "description_en": "Publish the status of a single availability topic."
    },
    {
      "action_name": "auto-publish_state",
      "description": "发布单个状态主题数据。",
      "description_en": "Publish data for a single state topic."
    },
    {
      "action_name": "auto-publish_hass",
      "description": "发布 Home Assistant 自动发现配置主题。",
      "description_en": "Publish Home Assistant discovery configuration topics."
    },
    {
      "action_name": "auto-startup_client",
      "description": "启动 MQTT 客户端主循环。",
      "description_en": "Start the main MQTT client loop."
    },
    {
      "action_name": "auto-clientLoop",
      "description": "运行客户端循环流程。",
      "description_en": "Run the client loop process."
    }
  ]
}

